function layout(title, subtitle, w, h){
  return { w:w, h:h, titleSize:Math.round(w*0.085), subSize:Math.round(w*0.032),
           titleX:Math.round(w*0.08), titleY:Math.round(h*0.42), subY:Math.round(h*0.42)+Math.round(w*0.06) };
}
function posterSVG(title, subtitle, bg, accent){
  var L=layout(title,subtitle,800,1000);
  return '<svg width="800" height="1000"><rect width="800" height="1000" fill="'+bg+'"/>'
    +'<rect x="40" y="40" width="720" height="920" fill="none" stroke="'+accent+'" stroke-width="4"/>'
    +'<text x="64" y="'+L.titleY+'" font-size="'+L.titleSize+'" fill="#fff" font-family="sans-serif">'+title+'</text>'
    +'<text x="64" y="'+L.subY+'" font-size="'+L.subSize+'" fill="'+accent+'" font-family="sans-serif">'+subtitle+'</text></svg>';
}
var EXPORTS={layout:layout, posterSVG:posterSVG};


